      "const MOON = \"#dfeee8\", JADE = \"#7fe3c0\", ROSE = \"#ff8fa3\", DIM = \"#6f9a93\";\nconst HEAD = '\"Playfair Display\", Georgia, serif';\n// the far sky: tiny stars breathing slowly\nconst sky = (n = 44) => {\n  ctx.save();\n  for (let i = 0; i < n; i++) {\n    ctx.globalAlpha = 0.1 + 0.22 * (0.5 + 0.5 * Math.sin(s.t * 1.3 + i * 1.7));\n    ctx.fillStyle = MOON;\n    ctx.fillRect(s.rand(i) * 720, 40 + s.rand(i + 60) * 800, 2.4, 2.4);\n  }\n  ctx.restore();\n};\n// one star: a soft halo and a bright core, k = 0..1 as it appears\nconst star = (x, y, r, c, k = 1) => {\n  if (k <= 0) return;\n  ctx.save();\n  ctx.fillStyle = c;\n  ctx.globalAlpha *= 0.16;\n  ctx.beginPath(); ctx.arc(x, y, Math.min(r * 3.2, r + 11) * k, 0, 7); ctx.fill();\n  ctx.globalAlpha /= 0.16;\n  ctx.beginPath(); ctx.arc(x, y, r * k, 0, 7); ctx.fill();\n  ctx.restore();\n};\nconst link = (a, b, c, k = 1, w = 2) => {\n  if (k <= 0) return;\n  ctx.save();\n  ctx.strokeStyle = c; ctx.globalAlpha *= 0.6; ctx.lineWidth = w; ctx.lineCap = \"round\";\n  ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k); ctx.stroke();\n  ctx.restore();\n};\n// a constellation: stars light up in order from t0, a line draws once both its stars are lit\nconst rasi = (pts, links, t0, gap = 0.1, c = MOON) => {\n  links.forEach(([a, b]) => link(pts[a], pts[b], c, s.at(t0 + Math.max(a, b) * gap, 0.25)));\n  pts.forEach((p, i) => star(p[0], p[1], p[2] ?? 5, c, s.pop(t0 + i * gap, 0.3)));\n};\n// a person as a constellation, feet at (x, y): the head is the biggest star\nconst POSES = {\n  stand: [[0, -196, 9], [0, -160], [-34, -110], [34, -110], [0, -86], [-20, -42], [20, -42], [-24, 0], [24, 0]],\n  reach: [[0, -196, 9], [0, -160], [-30, -112], [36, -218], [0, -86], [-20, -42], [20, -42], [-24, 0], [24, 0]],\n  // side on, hugging one raised knee with the head bowed (both arms and both legs overlap)\n  sit: [[34, -122, 9], [0, -100], [50, -60], [50, -60], [-32, -6], [62, -72], [62, -72], [78, 0], [78, 0]],\n};\nconst BODY = [[0, 1], [1, 2], [1, 3], [1, 4], [4, 5], [4, 6], [5, 7], [6, 8]];\nconst person = (x, y, k, pose, t0, c = MOON, gap = 0.05) =>\n  rasi(POSES[pose].map(([a, b, r]) => [x + a * k, y + b * k, (r ?? 4.5) * Math.max(k, 0.7)]), BODY, t0, gap, c);\nconst word = (str, x, y, size, c, a = 1) => {\n  if (a <= 0) return;\n  ctx.save();\n  ctx.globalAlpha *= a; ctx.font = \"900 \" + size + 'px ' + HEAD; ctx.textAlign = \"center\"; ctx.textBaseline = \"middle\"; ctx.fillStyle = c;\n  ctx.fillText(str, x, y);\n  ctx.restore();\n};\n// a seated figure under a sky of stars that stay unconnected; one rose star fades away\nsky();\nconst far = [[150, 250], [290, 180], [430, 280], [570, 200], [510, 420], [200, 410]];\nfar.forEach((p, i) => star(p[0], p[1], 4, DIM, s.pop(0.1 + i * 0.08, 0.3)));\nperson(330, 720, 1.5, \"sit\", 0.5);\nconst fall = s.at(1.5, 1.2);\nstar(s.lerp(430, 470, fall), s.lerp(350, 560, fall), 7, ROSE, s.pop(1.2, 0.3) * (1 - fall));\nword(\"sia-sia?\", 360, 110, 54, ROSE, s.at(2.0, 0.5));\ns.sfx(\"tick\", 0.5, 0.3);\ns.sfx(\"swish\", 1.5, 0.3);"
