      "const GRN = \"#0d4a3c\", DGRN = \"#072c23\", SAL = \"#ff8c69\", DSAL = \"#d8653f\", CRM = \"#fff1dc\";\nconst HEAD = '\"Archivo Black\", \"Arial Black\", sans-serif';\n// the edge runs from (0, a) to (720, b); side = 0 is above it, 1 below it\nconst side = (a, b, which) => {\n  ctx.beginPath();\n  if (which === 0) { ctx.moveTo(0, 0); ctx.lineTo(720, 0); ctx.lineTo(720, b); ctx.lineTo(0, a); }\n  else { ctx.moveTo(0, a); ctx.lineTo(720, b); ctx.lineTo(720, 1280); ctx.lineTo(0, 1280); }\n  ctx.closePath();\n};\nconst field = (a, b) => {\n  ctx.save();\n  side(a, b, 0); ctx.fillStyle = GRN; ctx.fill();\n  side(a, b, 1); ctx.fillStyle = SAL; ctx.fill();\n  ctx.restore();\n};\n// paints twice, each clipped to one side: main/shade are that side's opposite colours\nconst both = (a, b, paint) => {\n  ctx.save(); side(a, b, 0); ctx.clip(); paint(SAL, DSAL, GRN); ctx.restore();\n  ctx.save(); side(a, b, 1); ctx.clip(); paint(GRN, DGRN, SAL); ctx.restore();\n};\n// a flat slab with a thick side below it\nconst slab = (x, y, w, h, c, shade, d = 14, r = 16) => {\n  ctx.fillStyle = shade; ctx.beginPath(); ctx.roundRect(x, y + d, w, h, r); ctx.fill();\n  ctx.fillStyle = c; ctx.beginPath(); ctx.roundRect(x, y, w, h, r); ctx.fill();\n};\nconst disc = (x, y, r, c) => { ctx.fillStyle = c; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill(); };\nconst word = (str, x, y, size, c, o = {}) => {\n  ctx.font = \"400 \" + size + \"px \" + HEAD; ctx.textAlign = o.align ?? \"center\"; ctx.textBaseline = \"middle\"; ctx.fillStyle = c;\n  ctx.fillText(str, x, y);\n};\n// a coin drops through the edge, flipping colour as it crosses, and rolls out of the frame\nconst tilt = s.ease.inOut(s.clamp(s.t / 0.5, 0, 1));\nconst a = s.lerp(120, 300, tilt), b = s.lerp(120, 520, tilt);\nfield(a, b);\nconst fall = s.clamp((s.t - 0.3) / 0.8, 0, 1);\nconst roll = s.ease.inOut(s.clamp((s.t - 1.6) / 1.1, 0, 1));\nconst y = s.lerp(-110, 660, fall * fall) - Math.abs(Math.sin(s.clamp((s.t - 1.1) / 0.5, 0, 1) * Math.PI)) * 90;\nconst x = s.lerp(360, 900, roll);\nboth(a, b, (main, shade, back) => {\n  disc(x, y + 12, 104, shade);\n  disc(x, y, 104, main);\n  disc(x, y, 70, back);\n  word(\"Rp\", x, y + 2, 52, main);\n});\nctx.save();\nctx.globalAlpha *= s.at(1.3, 0.3);\nword(\"LEWAT\", 360, 180, 76, CRM);\nctx.restore();\ns.sfx(\"whoosh\", 0.3, 0.4);\ns.sfx(\"thud\", 1.1, 0.5);\ns.sfx(\"whoosh\", 1.6, 0.3);"
