      "const SUMI = s.theme === \"night\" ? \"#efe9dc\" : \"#17140f\", SEAL = \"#c8302c\";\nconst flat = { wobble: 0, hatch: false };\n// a brush stroke along pts, painted over [t0, t0 + len]: thick in the middle, tapering at both\n// ends (never thinner than minT of it), a little dry and uneven; w is the widest radius\nconst brush = (pts, t0, len, w, col = SUMI, minT = 0) => {\n  const k = s.at(t0, len);\n  if (k <= 0) return;\n  const seg = [];\n  let tot = 0;\n  for (let i = 1; i < pts.length; i++) { const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); seg.push(d); tot += d; }\n  const n = Math.max(2, Math.floor(tot / 3)), upto = Math.floor(n * k);\n  let si = 0, acc = 0;\n  for (let j = 0; j <= upto; j++) {\n    let r = (j / n) * tot;\n    while (si < seg.length - 1 && r > acc + seg[si]) { acc += seg[si]; si++; }\n    const f = seg[si] ? (r - acc) / seg[si] : 0, x = pts[si][0] + (pts[si + 1][0] - pts[si][0]) * f, y = pts[si][1] + (pts[si + 1][1] - pts[si][1]) * f;\n    const p = j / n, taper = Math.max(minT, Math.min(1, p * 5) * Math.min(1, (1 - p) * 3 + 0.15));\n    const rad = w * taper * (0.85 + 0.15 * Math.sin(j * 1.7));\n    s.circle(x, y, Math.max(0.8, rad), { fill: col, stroke: \"none\", alpha: 0.8 + 0.2 * Math.sin(j * 0.9), ...flat });\n  }\n};\n// an ink bloom soaking into the paper\nconst bloom = (x, y, r, k) => {\n  if (k <= 0) return;\n  ctx.save();\n  const g = ctx.createRadialGradient(x, y, 0, x, y, r * k);\n  g.addColorStop(0, s.theme === \"night\" ? \"rgba(239,233,220,0.22)\" : \"rgba(23,20,15,0.22)\");\n  g.addColorStop(1, \"rgba(0,0,0,0)\");\n  ctx.fillStyle = g;\n  ctx.fillRect(x - r, y - r, r * 2, r * 2);\n  ctx.restore();\n};\n// the red seal, pressed on\nconst seal = (x, y, t0, mark = \"sabar\") => {\n  const k = s.pop(t0, 0.3);\n  if (k <= 0) return;\n  s.group({ x, y, rotate: -0.05, scale: 1.25 - 0.25 * k }, () => {\n    s.rect(-46, -46, 92, 92, { r: 6, fill: SEAL, stroke: \"none\", wobble: 1.2, hatch: false, alpha: Math.min(1, k * 1.5) });\n    s.text(mark, 0, 2, { size: 22, color: \"#fbefe4\" });\n  });\n};\n// one circle in a single breath, left open at the end\nconst pts = [];\nfor (let i = 0; i <= 60; i++) { const a = -Math.PI * 0.4 + (i / 60) * Math.PI * 1.85; pts.push([360 + Math.cos(a) * 190, 520 + Math.sin(a) * 190]); }\nbloom(250, 400, 140, s.at(0.1, 0.8));\nbrush(pts, 0.2, 1.6, 22);\ns.sfx(\"swish\", 0.2, 0.4);"
