      "const INK = s.theme === \"night\" ? \"#f1f3f2\" : \"#1d1f22\", TQ = \"#0f9b8e\", HL = \"rgba(255,221,64,0.75)\";\nconst mk = (c = INK, w = 6) => ({ stroke: c, width: w, wobble: 1.4, hatch: false });\n// the point a fraction k along a polyline\nconst along = (pts, k) => {\n  const L = [];\n  let tot = 0;\n  for (let i = 1; i < pts.length; i++) { const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); L.push(d); tot += d; }\n  let r = tot * s.clamp(k, 0, 1);\n  for (let i = 0; i < L.length; i++) { if (r <= L[i]) { const f = L[i] ? r / L[i] : 0; return [pts[i][0] + (pts[i + 1][0] - pts[i][0]) * f, pts[i][1] + (pts[i + 1][1] - pts[i][1]) * f]; } r -= L[i]; }\n  return pts[pts.length - 1];\n};\n// a chunky marker whose tip sits at (x, y), cap colour c\nconst marker = (x, y, c = INK) => s.group({ x, y, rotate: 0.6 }, () => {\n  s.rect(-9, -150, 30, 120, { r: 8, fill: \"#f4f4f2\", stroke: INK, width: 3, wobble: 0, hatch: false });\n  s.rect(-9, -150, 30, 40, { r: 8, fill: c, stroke: INK, width: 3, wobble: 0, hatch: false });\n  s.shape([[-6, -30], [18, -30], [10, 0], [2, 0]], { fill: c, stroke: INK, width: 2, wobble: 0, hatch: false });\n});\n// a path drawn by the marker over [t0, t0 + len]; the marker rides its tip while it draws\nlet pen = null;\nconst ink = (pts, t0, len, c = INK, w = 6) => {\n  const k = s.at(t0, len);\n  if (k <= 0) return;\n  s.polyline(pts, { ...mk(c, w), draw: k });\n  if (k < 1) pen = [...along(pts, k), c];\n};\nconst box = (x, y, w, h) => [[x, y], [x + w, y + 2], [x + w - 2, y + h], [x + 2, y + h - 1], [x, y]];\nconst done = () => { if (pen) marker(pen[0], pen[1], pen[2]); };\n// a checklist; each line gets its tick, the last one with a highlighter swipe\nconst items = [\"video tutorial\", \"foto produk\", \"live tanya jawab\"];\n// the highlighter goes under the last line\nif (s.t > 1.8) s.rect(184, 540, 330 * s.at(1.8, 0.3), 40, { fill: HL, stroke: \"none\", wobble: 0, hatch: false });\nitems.forEach((it, i) => {\n  const y = 300 + i * 130;\n  s.polyline(box(90, y - 30, 60, 60), mk());\n  s.text(it, 190, y, { size: 38, color: INK, align: \"left\" });\n  ink([[100, y], [118, y + 20], [150, y - 34]], 0.3 + i * 0.5, 0.25, TQ, 8);\n  s.sfx(\"tick\", 0.45 + i * 0.5, 0.5);\n});\ndone();"
