      "paper",
      "const BK = \"#141414\", WH = \"#f2f0ea\", G1 = \"#9a9893\", G2 = \"#5e5c58\";\nconst flat = { wobble: 0, hatch: false };\n// halftone shading: dots on a grid whose size follows tone(x, y) 0..1, clipped by inside(x, y)\nconst tone = (x0, y0, x1, y1, step, inside, dark, col = BK) => {\n  for (let y = y0; y < y1; y += step)\n    for (let x = x0 + ((y / step) % 2) * step * 0.5; x < x1; x += step) {\n      const r = (step / 2) * Math.sqrt(s.clamp(dark(x, y), 0, 1));\n      if (r > 0.6 && inside(x, y)) s.circle(x, y, r, { fill: col, stroke: \"none\", ...flat });\n    }\n};\n// a photo print: white border, a halftone room with a window, slightly turned\nconst print = (x, y, rot, k = 1, sc = 1) => {\n  if (k <= 0) return;\n  s.group({ x, y, rotate: rot, scale: k * sc }, () => {\n    s.rect(-110 + 6, -90 + 8, 220, 180, { fill: \"#000000\", stroke: \"none\", alpha: 0.35, ...flat });\n    s.rect(-110, -90, 220, 180, { fill: WH, stroke: \"none\", ...flat });\n    s.rect(-96, -76, 192, 130, { fill: G1, stroke: \"none\", ...flat });\n    tone(-96, -76, 96, 54, 8, () => true, (px, py) => 0.15 + 0.5 * ((py + 76) / 130));\n    s.rect(-50, -60, 56, 56, { fill: WH, stroke: BK, width: 3, ...flat });\n    s.line(-22, -60, -22, -4, { stroke: BK, width: 3, ...flat });\n    s.rect(20, 10, 66, 34, { fill: G2, stroke: \"none\", ...flat });\n  });\n};\n// projector flicker: a faint frame-to-frame wash\nconst flicker = () => s.rect(0, 0, 720, 1280, { fill: s.rand(Math.floor(s.t * 24)) < 0.5 ? \"#ffffff\" : \"#000000\", stroke: \"none\", alpha: 0.03 + s.rand(Math.floor(s.t * 24) + 7) * 0.04, ...flat });\n// photos land one after another and pile up\nconst spots = [[220, 380, -0.12], [470, 340, 0.09], [300, 560, 0.05], [500, 620, -0.08], [250, 760, 0.11]];\nspots.forEach(([x, y, r], i) => {\n  const t0 = 0.15 + i * 0.28, k = s.ease.out(s.clamp((s.t - t0) / 0.25, 0, 1));\n  if (k > 0) print(x, y - (1 - k) * 60, r, 1, 1.25 - 0.25 * k);\n  s.sfx(\"shutter\", t0, 0.4);\n});\nflicker();"
