      "const DG = \"#2f4a3a\", SG = \"#6f8f72\", SG2 = \"#a9bfa5\", WH = \"#ffffff\", TC = \"#d9734e\", CR = \"#f5f2ea\";\nconst flat = { wobble: 0, hatch: false };\nconst line = { stroke: DG, width: 3, ...flat };\nconst glow = (x, y, r, a) => { for (let i = 3; i > 0; i--) s.circle(x, y, r * (0.7 + i * 0.3), { fill: TC, stroke: \"none\", alpha: a * 0.1, ...flat }); };\n// leaves drifting down and swaying, looping\nconst leaves = (n, x0, x1, y0, y1, a = 1) => {\n  for (let i = 0; i < n; i++) {\n    const p = (s.t * 0.18 + s.rand(i)) % 1, x = s.lerp(x0, x1, s.rand(i + 7)) + Math.sin(s.t * 1.3 + i) * 24;\n    s.group({ x, y: s.lerp(y0, y1, p), rotate: Math.sin(s.t * 2 + i) * 0.8 }, () => s.ellipse(0, 0, 11, 5, { fill: i % 3 ? SG : TC, stroke: \"none\", alpha: a * Math.min(1, (1 - p) * 3), ...flat }));\n  }\n};\n// the sun climbs slowly out of the horizon, then a pair of shoes waits on the floor\nconst r = s.ease.out(s.clamp(s.t / 2.2, 0, 1));\nglow(360, 900 - 220 * r, 70, r);\ns.circle(360, 900 - 220 * r, 62, { fill: TC, stroke: \"none\", ...flat });\nfor (const [x, t0] of [[300, 1.0], [420, 1.2]]) {\n  const k = s.at(t0, 0.5);\n  if (k <= 0) continue;\n  s.group({ x, y: 930 - (1 - k) * 14, alpha: k }, () => {\n    s.rect(-48, -30, 96, 30, { r: 14, fill: CR, ...line });\n    s.rect(-48, -8, 96, 10, { r: 5, fill: SG, stroke: \"none\", ...flat });\n    s.line(-14, -26, 6, -22, line);\n  });\n}\ns.sfx(\"rise\", 0, 0.3);\ns.sfx(\"bubble\", 1.0, 0.3);"
