      "const DG = \"#2f4a3a\", SG = \"#6f8f72\", SG2 = \"#a9bfa5\", WH = \"#ffffff\", TC = \"#d9734e\", CR = \"#f5f2ea\";\nconst flat = { wobble: 0, hatch: false };\nconst line = { stroke: DG, width: 3, ...flat };\nconst glow = (x, y, r, a) => { for (let i = 3; i > 0; i--) s.circle(x, y, r * (0.7 + i * 0.3), { fill: TC, stroke: \"none\", alpha: a * 0.1, ...flat }); };\n// leaves drifting down and swaying, looping\nconst leaves = (n, x0, x1, y0, y1, a = 1) => {\n  for (let i = 0; i < n; i++) {\n    const p = (s.t * 0.18 + s.rand(i)) % 1, x = s.lerp(x0, x1, s.rand(i + 7)) + Math.sin(s.t * 1.3 + i) * 24;\n    s.group({ x, y: s.lerp(y0, y1, p), rotate: Math.sin(s.t * 2 + i) * 0.8 }, () => s.ellipse(0, 0, 11, 5, { fill: i % 3 ? SG : TC, stroke: \"none\", alpha: a * Math.min(1, (1 - p) * 3), ...flat }));\n  }\n};\n// a winding path into the distance, footprints appearing one after another along it\nconst px = (f) => 360 + Math.sin(f * 3.2) * 70 * (1 - f * 0.7);\nconst d = s.at(0, 0.8);\nfor (let i = 0; i < 24 * d; i++) {\n  const f = i / 24, g = (i + 1.3) / 24;\n  s.line(px(f), 930 - f * 380, px(g), 930 - g * 380, { stroke: SG2, width: 70 * (1 - f * 0.8), ...flat });\n}\nfor (let i = 0; i < 10; i++) {\n  const f = (i + 0.5) / 12, k = s.at(0.7 + i * 0.16, 0.2);\n  if (k <= 0) continue;\n  const x = 360 + Math.sin(f * 3.2) * 70 * (1 - f * 0.7) + (i % 2 ? 10 : -10), y = 930 - f * 380;\n  s.ellipse(x, y, 7 * (1 - f * 0.5), 11 * (1 - f * 0.5), { fill: DG, stroke: \"none\", alpha: k * 0.7, ...flat });\n  if (i % 2 === 0) s.sfx(\"tap\", 0.7 + i * 0.16, 0.15);\n}\nconst p = s.at(2.0, 0.5);\nif (p > 0) s.text3d(\"10 MENIT\", 360, 470 - p * 10, { size: 20, depth: 0, color: WH, frame: \"pill\", frameColor: DG, alpha: p });"
