      "const ICE = \"#e6f4f1\", ACC = \"#ffb000\", DIM = \"#4d6461\";\nconst flat = { wobble: 0, hatch: false };\n// a word that slides up and fades in, left-aligned at (x, y)\nconst rise = (str, x, y, size, t0, col = ICE) => {\n  const k = s.ease.out(s.clamp((s.t - t0) / 0.35, 0, 1));\n  if (k <= 0) return;\n  s.text3d(str, x, y + (1 - k) * size * 0.9, { size, depth: 0, color: col, align: \"left\", alpha: Math.min(1, k * 1.6) });\n};\n// one digit rolling like an odometer to its final value\nconst roll = (x, y, size, to, t0, len) => {\n  const f = s.ease.out(s.clamp((s.t - t0) / len, 0, 1)), v = f * (10 + to);\n  for (const d of [Math.floor(v), Math.floor(v) + 1]) {\n    const off = (d - v) * size * 1.05;\n    if (Math.abs(off) < size) s.text3d(String(d % 10), x, y + off, { size, depth: 0, color: ICE, alpha: 1 - Math.abs(off) / size });\n  }\n};\n// the target time drops in letter by letter, then a bar counts down the hours left\nconst t = \"22:00\";\nfor (let i = 0; i < t.length; i++) {\n  const k = s.ease.out(s.clamp((s.t - 0.2 - i * 0.12) / 0.3, 0, 1));\n  if (k <= 0) continue;\n  s.text3d(t[i], 150 + i * 105, 470 - (1 - k) * 160, { size: 190, depth: 12, side: \"#b37a00\", color: i === 2 ? ACC : ICE, alpha: k });\n  s.sfx(\"impact\", 0.2 + i * 0.12, 0.35);\n}\ns.text(\"TARGET MALAM INI\", 360, 300, { size: 18, color: ACC, alpha: s.at(0.9, 0.3) });\nconst f = s.ease.inOut(s.clamp((s.t - 1.1) / 1.2, 0, 1));\nfor (let i = 0; i < 8; i++) s.rect(110 + i * 64, 640, 52, 22, { r: 3, fill: i < Math.round(8 * f) ? ACC : DIM, stroke: \"none\", alpha: s.at(1.0, 0.3), ...flat });\ns.text(\"8 JAM TIDUR\", 360, 700, { size: 16, color: ICE, alpha: s.at(1.4, 0.3) * 0.7 });"
