      "paper",
      "const CH = \"#18181b\", SC = \"#26262b\", CO = \"#ff6a4d\", PE = \"#ffb38a\", CR = \"#f5efe6\", MU = \"#8c8780\";\nconst flat = { wobble: 0, hatch: false };\n// the phone at centre: a rounded body, a screen, and whatever is on it (drawn in screen space)\nconst phone = (x, y, k, screen) => {\n  if (k <= 0) return;\n  s.group({ x, y: y + (1 - k) * 260, alpha: Math.min(1, k * 1.5) }, () => {\n    s.rect(-150, -290, 300, 580, { r: 46, fill: \"#000000\", stroke: \"rgba(255,255,255,0.12)\", width: 3, ...flat });\n    s.rect(-134, -274, 268, 548, { r: 34, fill: CH, stroke: \"none\", ...flat });\n    s.rect(-34, -262, 68, 14, { r: 7, fill: \"#000000\", stroke: \"none\", ...flat });\n    screen();\n  });\n};\n// a feature tile: a rounded square with an icon drawn inside, popping in\nconst tile = (x, y, col, t0, icon) => {\n  const k = s.pop(t0, 0.35);\n  if (k <= 0) return;\n  s.group({ x, y: y + s.wave(1.2, 5, x), scale: k }, () => {\n    s.rect(-56, -56, 112, 112, { r: 28, fill: col, stroke: \"none\", ...flat });\n    icon();\n  });\n};\nconst big = (str, x, y, size, col, t0, align = \"left\") => {\n  const k = s.ease.out(s.clamp((s.t - t0) / 0.35, 0, 1));\n  if (k > 0) s.text3d(str, x, y + (1 - k) * 24, { size, depth: 0, color: col, align, alpha: k });\n};\n// the phone rises; on it a flashcard flips from Hello to Halo\nphone(360, 560, s.ease.out(s.clamp(s.t / 0.6, 0, 1)), () => {\n  const f = s.clamp((s.t - 1.0) / 0.4, 0, 1), w = Math.abs(Math.cos(f * Math.PI));\n  s.rect(-100 * w, -120, 200 * w, 220, { r: 22, fill: f < 0.5 ? CR : CO, stroke: \"none\", ...flat });\n  if (w > 0.2) s.text3d(f < 0.5 ? \"Hello\" : \"Halo\", 0, -10, { size: 44, depth: 0, color: f < 0.5 ? CH : CR, alpha: w });\n  s.text(\"5 MENIT / HARI\", 0, 170, { size: 18, color: PE, alpha: s.at(1.4, 0.3) });\n});\ns.sfx(\"whoosh\", 0, 0.4);\ns.sfx(\"pageflip\", 1.0, 0.5);"
