      "paper",
      "const GN = \"#12a37f\", PALE = \"#d5f2e8\", MU = \"#9a917f\";\nconst INK = s.theme === \"night\" ? \"#eef2ea\" : \"#24201a\";\nconst thin = (w = 4) => ({ stroke: INK, width: w, wobble: 0, hatch: false });\nconst acc = (w = 5) => ({ stroke: GN, width: w, wobble: 0, hatch: false });\nconst flat = { stroke: \"none\", wobble: 0, hatch: false };\n// a path runs out at a gap, then carries on in green past it to a flag\ns.polyline([[110, 470], [250, 470], [310, 410]], { ...thin(), draw: s.at(0.1, 0.6) });\nconst gap = s.pop(0.7, 0.3);\nif (gap > 0) { s.line(318, 386, 346, 414, thin(4)); s.line(346, 386, 318, 414, thin(4)); }\nconst g = s.at(1.1, 0.9);\ns.curve([[310, 410], [380, 330], [470, 380], [560, 300]], { ...acc(), draw: g });\nif (g > 0.95) {\n  s.line(560, 300, 560, 200, thin(4));\n  s.shape([[560, 200], [620, 218], [560, 236]], { fill: GN, ...flat });\n}\ns.sfx(\"swish\", 0.1, 0.3);\ns.sfx(\"swish\", 1.1, 0.3);\ns.sfx(\"ding\", 2.0, 0.4);"
