      "Coba lagi, pakai cara lain.",
      "cara lain.",
      "paper",
      "const GN = \"#12a37f\", PALE = \"#d5f2e8\", MU = \"#9a917f\";\nconst INK = s.theme === \"night\" ? \"#eef2ea\" : \"#24201a\";\nconst thin = (w = 4) => ({ stroke: INK, width: w, wobble: 0, hatch: false });\nconst acc = (w = 5) => ({ stroke: GN, width: w, wobble: 0, hatch: false });\nconst flat = { stroke: \"none\", wobble: 0, hatch: false };\n// two routes from one dot: the straight one hits a wall, the bend gets through\ns.circle(160, 470, 12, { fill: INK, ...flat });\ns.line(160, 470, 400, 470, { ...thin(), draw: s.at(0.2, 0.5) });\nconst w = s.pop(0.7, 0.3);\nif (w > 0) s.rect(410, 410, 20 * w, 120, { r: 4, ...thin(4) });\nconst b = s.at(1.1, 0.9);\ns.curve([[160, 470], [230, 330], [430, 290], [560, 400]], { ...acc(), draw: b });\nconst k = s.pop(1.9, 0.3);\nif (k > 0) { s.circle(560, 400, 24 * k, { fill: PALE, ...flat }); s.check(560, 400, 26 * k, { stroke: GN, width: 5, wobble: 0 }); }\ns.sfx(\"thud\", 0.7, 0.4);\ns.sfx(\"swish\", 1.1, 0.3);\ns.sfx(\"ding\", 1.9, 0.4);"
