      "paper",
      "const GN = \"#12a37f\", PALE = \"#d5f2e8\", MU = \"#9a917f\";\nconst INK = s.theme === \"night\" ? \"#eef2ea\" : \"#24201a\";\nconst thin = (w = 4) => ({ stroke: INK, width: w, wobble: 0, hatch: false });\nconst acc = (w = 5) => ({ stroke: GN, width: w, wobble: 0, hatch: false });\nconst flat = { stroke: \"none\", wobble: 0, hatch: false };\n// a staircase drawn in, a green dot hopping up one step at a time\nconst st = [[140, 520], [240, 520], [240, 450], [340, 450], [340, 380], [440, 380], [440, 310], [540, 310], [540, 240], [620, 240]];\ns.polyline(st, { ...thin(), draw: s.at(0.1, 0.8) });\nconst n = Math.min(4, Math.floor(s.clamp((s.t - 0.9) / 0.4, 0, 99)));\nconst f = s.clamp((s.t - 0.9) / 0.4, 0, 99) - n;\nconst x0 = 190 + n * 100, y0 = 520 - n * 70;\nconst hop = n < 4 ? Math.sin(Math.min(1, f) * Math.PI) * 40 : 0;\nconst x = x0 + (n < 4 ? Math.min(1, f) * 100 : 0), y = y0 - (n < 4 ? Math.min(1, f) * 70 : 0) - 22 - hop;\nif (s.t > 0.7) s.circle(x, y, 18, { fill: GN, ...flat });\nfor (let i = 0; i < 5; i++) if (s.t > 0.9 + i * 0.4) s.text(String(i + 1), 190 + i * 100, 548 - i * 70, { size: 16, color: MU });\nfor (let i = 0; i < 4; i++) s.sfx(\"tap\", 0.9 + i * 0.4, 0.3);"
