      "Nanti pintunya kebuka sendiri.",
      "kebuka",
      "night",
      "const GN = \"#12a37f\", PALE = \"#d5f2e8\", MU = \"#9a917f\";\nconst INK = s.theme === \"night\" ? \"#eef2ea\" : \"#24201a\";\nconst thin = (w = 4) => ({ stroke: INK, width: w, wobble: 0, hatch: false });\nconst acc = (w = 5) => ({ stroke: GN, width: w, wobble: 0, hatch: false });\nconst flat = { stroke: \"none\", wobble: 0, hatch: false };\n// a door frame drawn in, then the door swings open on a green glow\ns.rect(250, 190, 220, 340, { r: 6, ...thin(), draw: s.at(0.1, 0.7) });\ns.line(190, 530, 530, 530, { ...thin(), draw: s.at(0.3, 0.5) });\nconst o = s.ease.inOut(s.clamp((s.t - 1.0) / 0.9, 0, 1));\nif (o > 0) {\n  s.rect(256, 196, 208, 328, { r: 4, fill: PALE, ...flat });\n  for (let i = 0; i < 5; i++) s.line(360, 360, 360 + Math.cos(-2.6 + i * 0.5) * (80 + 40 * o), 360 + Math.sin(-2.6 + i * 0.5) * (80 + 40 * o), { stroke: GN, width: 4, alpha: o, wobble: 0, hatch: false });\n}\nconst w = 208 * (1 - 0.8 * o);\ns.shape([[256, 196], [256 + w, 196 + 30 * o], [256 + w, 524 - 30 * o], [256, 524]], { fill: s.theme === \"night\" ? \"#1b2a24\" : \"#ffffff\", stroke: INK, width: 4, wobble: 0, hatch: false });\ns.circle(256 + w - 22, 360, 7, { fill: INK, ...flat });\ns.sfx(\"swish\", 0.1, 0.3);\ns.sfx(\"rise\", 1.0, 0.4);"
