      "const CR = \"#e9f0ff\", SK = \"#6fd3ff\", MN = \"#7ef0b0\", PK = \"#ff6f91\";\nconst ln = (c = CR, w = 3) => ({ stroke: c, width: w, wobble: 0, hatch: false });\n// a path drawn in by the point of light, from t0 over len seconds\nconst pen = (pts, t0, len, c = CR, w = 3) => s.polyline(pts, { ...ln(c, w), draw: s.at(t0, len), pen: true });\n// the ground line, drawn left to right at the start and running on as the camera follows it\nconst ground = (pan = 0) => s.line(-40, 760, 760 + pan, 760, { ...ln(), draw: s.at(0, 0.6), pen: true });\n// a figure with a round head drawn part by part, feet at (x, 760); wave = the right arm waves\nconst figure = (x, h, t0, c = CR, o = {}) => {\n  const k = h / 200, y = 760, sw = o.wave ? s.wave(2.4, 16 * k) : 0;\n  s.circle(x, y - 172 * k, 22 * k, { ...ln(c), draw: s.at(t0, 0.3), pen: true });\n  pen([[x, y - 148 * k], [x + 4 * k, y - 110 * k], [x, y - 76 * k]], t0 + 0.25, 0.15, c);\n  pen([[x - 36 * k, y - 96 * k], [x - 14 * k, y - 124 * k], [x, y - 132 * k], [x + 18 * k, y - 140 * k], [x + 30 * k, y - 172 * k - sw]], t0 + 0.35, 0.25, c);\n  pen([[x - 26 * k, y], [x - 8 * k, y - 40 * k], [x, y - 76 * k], [x + 10 * k, y - 38 * k], [x + 30 * k, y]], t0 + 0.5, 0.25, c);\n};\n// a four-point star that pops in and twinkles\nconst star = (x, y, t0, c = MN) => {\n  const k = s.pop(t0, 0.3) * (0.75 + 0.25 * Math.sin(s.t * 5 + x));\n  if (k <= 0) return;\n  const r = 14 * k, q = 3 * k;\n  s.polyline([[x, y - r], [x + q, y - q], [x + r, y], [x + q, y + q], [x, y + r], [x - q, y + q], [x - r, y], [x - q, y - q], [x, y - r]], ln(c, 2.5));\n};\n// a capsule bar on the ground line from x, w wide, filled with a grid of dots from frac a to b\nconst bar = (x, w, t0) => s.rect(x, 640, w, 100, { ...ln(), r: 40, draw: s.at(t0, 0.7), pen: true });\nconst dots = (x, w, a, b, t0, c) => {\n  const cols = Math.round(w / 22), from = Math.round(a * cols), to = Math.round(b * cols);\n  for (let i = from; i < to; i++)\n    for (let j = 0; j < 3; j++) {\n      const k = s.pop(t0 + (i - from) * 0.04 + j * 0.02, 0.2);\n      if (k > 0) s.circle(x + 14 + i * 22 * ((w - 28) / (w - 22)), 662 + j * 28, 4 * k, { fill: c, stroke: c, width: 0, wobble: 0, hatch: false });\n    }\n};\n// a figure holds a wallet, and the money slips out along a dashed curve\nground();\nfigure(250, 240, 0.4, CR);\npen([[330, 600], [440, 600], [440, 680], [330, 680], [330, 600]], 1.0, 0.4);\npen([[400, 625], [440, 625], [440, 655], [400, 655]], 1.3, 0.2, SK);\nconst d = s.at(1.6, 0.6);\ns.dash(450, 600, 540, 480, { ...ln(PK, 2.5), draw: s.clamp(d * 2, 0, 1) });\ns.dash(540, 480, 640, 430, { ...ln(PK, 2.5), draw: s.clamp(d * 2 - 1, 0, 1) });\nconst m = s.at(2.0, 0.4);\nif (m > 0) s.text(\"habis\", 600, 380 - (1 - m) * 18, { size: 40, color: PK, alpha: m });\ns.sfx(\"swish\", 0.0, 0.4);\ns.sfx(\"swish\", 1.0, 0.4);\ns.sfx(\"whoosh\", 1.6, 0.4);"
