      "const NV = \"#0b224f\", NV2 = \"#081a3d\", YE = \"#fed509\", WH = \"#f4f7ff\", MU = \"#8e9bb8\", LINE = \"rgba(150,180,240,0.3)\";\nconst SANS = '\"Poppins\", \"Segoe UI\", sans-serif', MONO = '\"Space Mono\", \"Courier New\", monospace';\nconst txt = (str, x, y, size, c, o = {}) => {\n  ctx.font = (o.weight ?? 700) + \" \" + size + \"px \" + (o.font ?? SANS);\n  ctx.textAlign = o.align ?? \"left\"; ctx.textBaseline = \"middle\"; ctx.fillStyle = c;\n  if (\"letterSpacing\" in ctx) ctx.letterSpacing = (o.spacing ?? 0) + \"px\";\n  ctx.fillText(str, x, y);\n  if (\"letterSpacing\" in ctx) ctx.letterSpacing = \"0px\";\n};\n// fades in while rising, from second t0; fn draws in place\nconst enter = (t0, fn, dy = 16, len = 0.45) => {\n  const k = s.ease.out(s.clamp((s.t - t0) / len, 0, 1));\n  if (k <= 0) return;\n  ctx.save(); ctx.globalAlpha *= k; ctx.translate(0, (1 - k) * dy); fn(k); ctx.restore();\n};\n// the step marker: a small yellow square with the number, the step's name beside it\nconst step = (n, title, t0 = 0, x = 60, y = 380) => enter(t0, () => {\n  ctx.fillStyle = YE; ctx.beginPath(); ctx.roundRect(x, y - 18, 36, 36, 7); ctx.fill();\n  txt(String(n), x + 18, y + 1, 22, NV2, { align: \"center\", weight: 800 });\n  txt(title, x + 50, y + 1, 26, WH);\n});\n// a mono caps label in a thin frame; returns its width\nconst tag = (str, x, y, t0 = 0, c = WH) => {\n  ctx.font = \"400 15px \" + MONO;\n  const w = ctx.measureText(str).width + str.length * 2 + 22;\n  enter(t0, () => {\n    ctx.strokeStyle = \"rgba(220,230,255,0.7)\"; ctx.lineWidth = 1.5;\n    ctx.beginPath(); ctx.roundRect(x, y - 15, w, 30, 3); ctx.stroke();\n    txt(str, x + 11, y + 1, 15, c, { font: MONO, weight: 400, spacing: 2 });\n  }, 8);\n  return w;\n};\n// a UI card: navy with a thin light edge and a soft shadow (o.fill \"#ffffff\" for a call to action)\nconst card = (x, y, w, h, o = {}) => {\n  ctx.save();\n  ctx.shadowColor = \"rgba(0,0,0,0.4)\"; ctx.shadowBlur = 30; ctx.shadowOffsetY = 12;\n  const g = ctx.createLinearGradient(0, y, 0, y + h);\n  g.addColorStop(0, o.fill ?? \"#0e2a5e\"); g.addColorStop(1, o.fill ?? NV);\n  ctx.fillStyle = g; ctx.beginPath(); ctx.roundRect(x, y, w, h, o.r ?? 16); ctx.fill();\n  ctx.restore();\n  if (!o.fill) { ctx.strokeStyle = LINE; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.roundRect(x, y, w, h, o.r ?? 16); ctx.stroke(); }\n};\n// a yellow tick in a circle that pops in at t0\nconst check = (x, y, t0, r = 15) => {\n  const k = s.ease.back(s.clamp((s.t - t0) / 0.3, 0, 1));\n  if (k <= 0) return;\n  ctx.save(); ctx.translate(x, y); ctx.scale(k, k);\n  ctx.fillStyle = YE; ctx.beginPath(); ctx.arc(0, 0, r, 0, 7); ctx.fill();\n  ctx.strokeStyle = NV2; ctx.lineWidth = 3.2; ctx.lineCap = \"round\"; ctx.lineJoin = \"round\";\n  ctx.beginPath(); ctx.moveTo(-r * 0.42, 0); ctx.lineTo(-r * 0.1, r * 0.32); ctx.lineTo(r * 0.45, -r * 0.3); ctx.stroke();\n  ctx.restore();\n};\n// one row of a checklist card: an icon box, the title, a mono note, ticked at done\nconst row = (x, y, w, title, note, t0, done) => enter(t0, () => {\n  ctx.fillStyle = \"rgba(255,255,255,0.04)\"; ctx.strokeStyle = LINE; ctx.lineWidth = 1.2;\n  ctx.beginPath(); ctx.roundRect(x, y, w, 64, 12); ctx.fill(); ctx.stroke();\n  ctx.strokeStyle = \"rgba(220,230,255,0.55)\"; ctx.lineWidth = 1.6; ctx.beginPath(); ctx.roundRect(x + 16, y + 20, 24, 24, 5); ctx.stroke();\n  txt(title, x + 56, y + 25, 21, WH, { weight: 600 });\n  txt(note, x + 56, y + 46, 11, MU, { font: MONO, weight: 400, spacing: 1.5 });\n  if (done !== undefined) check(x + w - 32, y + 32, done);\n}, 14);\n// counter tiles 1..n: the first `filled` are yellow (the newest pops at t0)\nconst tiles = (x, y, w, n, filled, t0 = 0) => {\n  const gap = 10, tw = (w - gap * (n - 1)) / n;\n  for (let i = 0; i < n; i++) {\n    const on = i < filled - 1 ? 1 : i === filled - 1 ? s.clamp((s.t - t0) / 0.2, 0, 1) : 0;\n    ctx.fillStyle = NV2; ctx.strokeStyle = \"rgba(150,180,240,0.35)\"; ctx.lineWidth = 1.5;\n    ctx.beginPath(); ctx.roundRect(x + i * (tw + gap), y, tw, 38, 6); ctx.fill(); ctx.stroke();\n    if (on > 0) { ctx.save(); ctx.globalAlpha *= on; ctx.fillStyle = YE; ctx.beginPath(); ctx.roundRect(x + i * (tw + gap), y, tw, 38, 6); ctx.fill(); ctx.restore(); }\n    txt(String(i + 1), x + i * (tw + gap) + tw / 2, y + 20, 18, on > 0.5 ? NV2 : MU, { align: \"center\", weight: 700 });\n  }\n};\n// the chapter ruler under the picture: chapter name, tick marks, this chapter in yellow between its neighbours\nconst ruler = (title, names, at = 1) => {\n  const y = 900, mid = 360;\n  txt(title, mid, y, 26, WH, { align: \"center\" });\n  ctx.strokeStyle = \"rgba(150,180,240,0.35)\"; ctx.lineWidth = 1.5;\n  for (let x = 54; x <= 666; x += 34) {\n    const major = Math.abs(x - mid) % 238 < 1 || Math.abs(x - 122) < 1 || Math.abs(x - 598) < 1;\n    ctx.beginPath(); ctx.moveTo(x, y + 40 - (major ? 10 : 4)); ctx.lineTo(x, y + 40 + (major ? 10 : 4)); ctx.stroke();\n  }\n  ctx.strokeStyle = WH; ctx.lineWidth = 2.5; ctx.beginPath(); ctx.moveTo(mid, y + 26); ctx.lineTo(mid, y + 54); ctx.stroke();\n  const xs = [mid - 238, mid, mid + 238];\n  names.forEach((n, i) => n && txt(n, xs[i - at + 1] ?? -99, y + 72, 15, i === at ? YE : \"rgba(142,155,184,0.55)\", { align: \"center\", font: MONO, weight: 400 }));\n};\n// the whole route at a glance: four numbered stops joined by a yellow line that fills as each is named\ntag(\"4 LANGKAH · DARI GAJIAN\", 60, 400, 0.1);\nconst names = [\"Catat\", \"Pisah\", \"Otomatis\", \"Tahan\"];\nconst xs = [110, 280, 450, 620], y = 520;\nconst fill = s.ease.inOut(s.clamp((s.t - 0.5) / 1.6, 0, 1));\nctx.strokeStyle = \"rgba(150,180,240,0.3)\"; ctx.lineWidth = 3;\nctx.beginPath(); ctx.moveTo(xs[0], y); ctx.lineTo(xs[3], y); ctx.stroke();\nctx.strokeStyle = YE; ctx.beginPath(); ctx.moveTo(xs[0], y); ctx.lineTo(s.lerp(xs[0], xs[3], fill), y); ctx.stroke();\nnames.forEach((n, i) => {\n  const t0 = 0.3 + i * 0.45;\n  enter(t0, () => {\n    const on = s.lerp(xs[0], xs[3], fill) >= xs[i] - 1;\n    ctx.fillStyle = on ? YE : NV2; ctx.strokeStyle = on ? YE : \"rgba(220,230,255,0.6)\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.arc(xs[i], y, 30, 0, 7); ctx.fill(); ctx.stroke();\n    txt(String(i + 1), xs[i], y + 1, 26, on ? NV2 : WH, { align: \"center\", weight: 800 });\n    txt(n, xs[i], y + 58, 21, WH, { align: \"center\", weight: 600 });\n  }, 12);\n  s.sfx(\"tick\", t0, 0.5);\n});\nenter(2.2, () => {\n  txt(\"▲ MULAI: GAJIAN\", 60, 640, 13, YE, { font: MONO, weight: 400, spacing: 1.5 });\n  txt(\"▲ SELESAI\", 660, 640, 13, YE, { font: MONO, weight: 400, spacing: 1.5, align: \"right\" });\n}, 6);\nruler(\"Mulai Nabung\", [\"\", \"Catat\", \"Pisah\"], 1);"
