      "const INK = s.theme === \"night\" ? \"#e9e0c8\" : \"#2b2418\", GN = \"#2f5d46\", RU = \"#9a4a2a\";\nconst ln = (w = 2.5, c = INK) => ({ stroke: c, width: w, wobble: 0.5, hatch: false });\n// engraving hatch: parallel slanted lines inside an ellipse, on its shaded side\nconst hatch = (cx, cy, rx, ry, k = 1, gap = 9, c = INK) => {\n  for (let d = -rx - ry; d < rx + ry; d += gap) {\n    const pts = [];\n    for (let t = -1; t <= 1; t += 0.02) {\n      const x = cx + d * 0.7 + t * rx, y = cy + t * ry * 0.9 - d * 0.3;\n      if (((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 < 0.95 && x - cx + (y - cy) > rx * 0.1) pts.push([x, y]);\n    }\n    if (pts.length > 1) s.polyline(pts, { stroke: c, width: 1.4, alpha: k, wobble: 0, hatch: false });\n  }\n};\n// the plate number and title, in the corner of the frame\nconst plate = (n, title) => {\n  s.text(\"No. \" + n, 120, 170, { size: 22, color: RU, align: \"left\", alpha: s.at(0, 0.3) });\n  s.text(title, 600, 170, { size: 22, color: INK, align: \"right\", alpha: s.at(0.1, 0.3) });\n};\n// a serif year counting up to its value\nconst year = (from, to, y, t0, len) => s.text3d(String(Math.round(from + (to - from) * s.ease.out(s.clamp((s.t - t0) / len, 0, 1)))), 360, y, { size: 96, depth: 0, color: INK });\nplate(\"I\", \"COFFEA ARABICA\");\nyear(1600, 1696, 280, 0.1, 1.2);\n// a branch drawn in, leaves, then cherries in rust\ns.curve([[180, 760], [300, 640], [420, 560], [560, 470]], { ...ln(4), draw: s.at(0.2, 0.7) });\n[[300, 640, -1], [380, 590, 1], [450, 545, -1], [520, 500, 1]].forEach(([x, y, sd], i) => {\n  const k = s.at(0.7 + i * 0.15, 0.3);\n  if (k <= 0) return;\n  s.group({ x, y, rotate: sd * 0.9 }, () => {\n    s.ellipse(0, -60 * k, 28 * k, 62 * k, { ...ln(2.5), fill: \"none\" });\n    s.line(0, 0, 0, -118 * k, ln(1.5));\n    for (let j = 1; j < 5; j++) s.line(0, -j * 24 * k, 18 * k, -j * 24 * k - 12 * k, ln(1));\n  });\n});\n[[340, 660], [365, 640], [470, 585], [492, 566]].forEach(([x, y], i) => {\n  const k = s.pop(1.4 + i * 0.1, 0.3);\n  if (k > 0) { s.circle(x, y, 16 * k, { ...ln(2.5, RU), fill: \"none\" }); hatch(x, y, 15 * k, 15 * k, 1, 5, RU); }\n});\ns.text(\"JAWA\", 360, 840, { size: 26, color: GN, alpha: s.at(1.8, 0.3) });\ns.sfx(\"pageflip\", 0.1, 0.4);"
