      "const BK = \"#0b0a0f\", AM = \"#ffb347\", AM2 = \"#ffd98a\";\nconst flat = { wobble: 0, hatch: false };\nconst HY = 845;\nconst sil = { fill: BK, stroke: \"none\", ...flat };\n// a warm light with its glow\nconst lamp = (x, y, r, k) => { if (k <= 0) return; for (let i = 3; i > 0; i--) s.circle(x, y, r * (1 + i * 0.9), { fill: AM, stroke: \"none\", alpha: 0.1 * k, ...flat }); };\n// a little V-shaped bird, flapping\nconst bird = (x, y, sc, ph) => { const f = Math.sin(s.t * 8 + ph) * 8 * sc; s.polyline([[x - 14 * sc, y - f], [x, y], [x + 14 * sc, y - f]], { stroke: BK, width: 3, ...flat }); };\n// a figure in silhouette\nconst figure = (x, y, size, pose, scarf) => s.person(x, y, { size, pose, shirt: BK, pants: BK, skin: BK, hairColor: BK, hair: scarf ? \"none\" : \"short\", hijab: scarf ? BK : null });\n// the house on the rise; its window lights up, smoke curls from the roof\ns.shape([[220, HY], [220, HY - 170], [360, HY - 270], [500, HY - 170], [500, HY]], sil);\ns.rect(430, HY - 290, 30, 80, sil);\nconst on = s.at(0.6, 0.5);\nlamp(300, HY - 110, 30, on);\ns.rect(272, HY - 140, 56, 60, { fill: on > 0 ? AM : \"#22202a\", stroke: \"none\", ...flat });\ns.line(300, HY - 140, 300, HY - 80, { stroke: BK, width: 4, ...flat });\nlamp(420, HY - 70, 18, on);\ns.rect(400, HY - 110, 40, 110, { fill: on > 0 ? AM2 : \"#22202a\", stroke: \"none\", alpha: 0.9, ...flat });\nfor (let i = 0; i < 5; i++) {\n  const p = (s.t * 0.3 + i / 5) % 1;\n  s.circle(445 + Math.sin(p * 6 + i) * 18, HY - 300 - p * 200, 14 + p * 22, { fill: \"#2a2733\", stroke: \"none\", alpha: (1 - p) * 0.5, ...flat });\n}\ns.sfx(\"click\", 0.6, 0.3);"
