      "const sunCols = [\"#ffe14d\", \"#ffcf3f\", \"#ffb23f\", \"#ff8f4a\", \"#ff6a5a\", \"#ff527a\", \"#ff4699\", \"#ff3fb8\", \"#ff3fd1\", \"#e03fe6\"];\nconst sun = (x, y, r) => {\n  ctx.save();\n  ctx.beginPath();\n  ctx.arc(x, y, r, 0, Math.PI * 2);\n  ctx.clip();\n  for (let i = 0; i < 10; i++) {\n    const band = (2 * r) / 10, gap = i > 4 ? (i - 4) * 3.5 : 0;\n    s.rect(x - r, y - r + i * band, 2 * r, band - gap, { fill: sunCols[i], stroke: \"none\" });\n  }\n  ctx.restore();\n};\ns.sfx(\"swish\", 0.2, 0.6);\ns.sfx(\"sparkle\", 1.2);\nconst P = \"#ff3fd1\", C = \"#29e7ff\";\nconst rise = s.ease.out(s.clamp(s.t / 1.2, 0, 1));\nctx.save();\nctx.beginPath();\nctx.rect(0, 0, 720, 640);\nctx.clip();\nsun(360, 560 - rise * 150, 190);\nctx.restore();\ns.line(40, 640, 680, 640, { stroke: C, width: 3 });\nconst palm = (x, h, dir, ph) => {\n  s.group({ x, y: 760, rotate: s.wave(0.9, 0.06, ph) * dir }, () => {\n    s.curve([[0, 0], [dir * 10, -h * 0.5], [dir * 30, -h]], { stroke: \"#1b0b2e\", width: 14 });\n    for (let i = 0; i < 6; i++) {\n      const a = -Math.PI / 2 + (i - 2.5) * 0.55 + s.wave(1.2, 0.05, i + ph);\n      const tx = dir * 30, ty = -h, L = 110;\n      s.curve([[tx, ty], [tx + Math.cos(a) * L * 0.6, ty + Math.sin(a) * L * 0.6 - 18], [tx + Math.cos(a) * L, ty + Math.sin(a) * L + 30]], { stroke: \"#1b0b2e\", width: 10, draw: s.at(0.3 + i * 0.05, 0.4) });\n    }\n  });\n};\npalm(140, 330, 1, 0);\npalm(590, 280, -1, 2);\ns.text(\"STAY RAD\", 360, 720, { size: 34, color: P, alpha: s.at(1.0, 0.3) });"
