      "gunung origami dua sisi (terang & bayangan) yang naik dari padang, lalu bendera koral muncul di puncak",
      "const CO = \"#ef6f5e\", MS = \"#f2b632\", NV = \"#2a3a63\", WH = \"#fbf8f0\", SN = \"#e9eef5\";\nconst flat = { wobble: 0, hatch: false };\n// a cut-paper shape on its soft shadow\nconst paper = (pts, fill, a = 1) => {\n  s.shape(pts.map(([x, y]) => [x + 5, y + 6]), { fill: \"#000000\", stroke: \"none\", alpha: 0.12 * a, ...flat });\n  s.shape(pts, { fill, stroke: \"none\", alpha: a, ...flat });\n};\n// the origami mountain: two folded faces, light and shade, with a snow cap; rises by k\nconst mountain = (k) => {\n  const y = 950 + (1 - k) * 500;\n  paper([[90, y], [360, y - 560], [630, y]], \"#6f7fa6\");\n  s.shape([[360, y - 560], [630, y], [420, y]], { fill: \"#56648a\", stroke: \"none\", ...flat });\n  s.shape([[360, y - 560], [300, y - 430], [338, y - 450], [360, y - 420], [392, y - 455], [420, y - 430]], { fill: SN, stroke: \"none\", ...flat });\n};\n// a little flag on a pole, waving\nconst flag = (x, y, k) => {\n  if (k <= 0) return;\n  s.rect(x - 3, y - 110 * k, 6, 110 * k, { fill: NV, stroke: \"none\", ...flat });\n  const w = s.wave(3, 8);\n  paper([[x + 3, y - 110 * k], [x + 70 * k, y - 92 * k + w], [x + 3, y - 70 * k]], CO);\n};\n// an origami crane: a body and two folded wings that flap\nconst crane = (x, y, sc, ph) => s.group({ x, y, scale: sc }, () => {\n  const f = Math.sin(s.t * 6 + ph) * 18;\n  paper([[-40, 0], [0, -10], [40, 0], [0, 8]], WH);\n  s.shape([[0, -8], [-14, -40 - f], [12, -6]], { fill: \"#e3ddd0\", stroke: \"none\", ...flat });\n  s.shape([[0, -8], [22, -38 - f], [14, -4]], { fill: WH, stroke: \"none\", ...flat });\n  s.shape([[38, 0], [54, -18], [44, 2]], { fill: WH, stroke: \"none\", ...flat });\n});\n// the folded mountain rises from the meadow, then the flag pops on its top\nmountain(s.ease.out(s.clamp(s.t / 1.0, 0, 1)));\nflag(360, 395, s.pop(1.1, 0.4));\ns.sfx(\"paper\", 0.1, 0.5);\ns.sfx(\"pop\", 1.1, 0.5);"
