      "teks telop tebal outline ganda yang meletup per huruf, cincin mengembang, konfeti bintang",
      "const NV = \"#1f1a3a\", PK = \"#ff4f9a\", YE = \"#ffd23a\", WH = \"#ffffff\", MI = \"#5fe0b5\", VI = \"#7b5cff\";\nconst flat = { wobble: 0, hatch: false };\n// telop: chunky rounded letters with a double outline and a hard shadow, popping in one by one\nconst telop = (str, x, y, size, fill, t0, step = 0.06) => {\n  ctx.save();\n  ctx.font = \"400 \" + size + 'px \"Lilita One\", \"Arial Rounded MT Bold\", sans-serif';\n  ctx.textBaseline = \"middle\";\n  ctx.lineJoin = \"round\";\n  // a little air between the letters so the thick outlines don't run together\n  const gap = size * 0.06;\n  const w = ctx.measureText(str).width + gap * (str.length - 1);\n  let cx = x - w / 2;\n  for (let i = 0; i < str.length; i++) {\n    const ch = str[i], cw = ctx.measureText(ch).width, k = s.pop(t0 + i * step, 0.35);\n    if (k > 0 && ch !== \" \") {\n      ctx.save();\n      ctx.translate(cx + cw / 2, y);\n      ctx.rotate((1 - Math.min(1, k)) * -0.5);\n      ctx.scale(k, k);\n      ctx.strokeStyle = NV; ctx.fillStyle = NV; ctx.lineWidth = size * 0.19;\n      ctx.strokeText(ch, -cw / 2 + 6, 8); ctx.fillText(ch, -cw / 2 + 6, 8);\n      ctx.strokeText(ch, -cw / 2, 0);\n      ctx.strokeStyle = WH; ctx.lineWidth = size * 0.1;\n      ctx.strokeText(ch, -cw / 2, 0);\n      ctx.fillStyle = fill;\n      ctx.fillText(ch, -cw / 2, 0);\n      ctx.restore();\n    }\n    cx += cw + gap;\n  }\n  ctx.restore();\n};\nconst ring = (x, y, t0, col) => {\n  const k = s.clamp((s.t - t0) / 0.9, 0, 1);\n  if (k > 0 && k < 1) s.circle(x, y, 60 + k * 260, { stroke: col, width: 8 * (1 - k) + 2, alpha: 1 - k, ...flat });\n};\nconst star = (x, y, r, col, rot) => s.shape(Array.from({ length: 10 }, (_, i) => { const a = rot + (i * Math.PI) / 5; const rr = i % 2 ? r * 0.45 : r; return [x + Math.cos(a) * rr, y + Math.sin(a) * rr]; }), { fill: col, stroke: NV, width: 3, ...flat });\nconst confetti = (t0, n = 18) => {\n  if (s.t < t0) return;\n  for (let i = 0; i < n; i++) {\n    const p = s.t - t0, x = 360 + (s.rand(i) - 0.5) * 640, y = 300 + (s.rand(i + 5) - 0.6) * 300 + p * (120 + s.rand(i + 9) * 160);\n    star(x, y, 9 + s.rand(i + 3) * 8, [YE, PK, MI, VI, WH][i % 5], p * 3 + i);\n  }\n};\nconst card = (x, y, sz, col, k, icon) => s.group({ x, y, scale: k, rotate: (1 - Math.min(1, k)) * 0.4 }, () => {\n  s.rect(-sz / 2 + 7, -sz / 2 + 8, sz, sz, { r: 24, fill: NV, stroke: \"none\", ...flat });\n  s.rect(-sz / 2, -sz / 2, sz, sz, { r: 24, fill: col, stroke: NV, width: 6, ...flat });\n  icon();\n});\nring(360, 470, 0.15, YE);\nring(360, 470, 0.45, WH);\ntelop(\"OLAHRAGA\", 360, 420, 104, YE, 0.1);\ntelop(\"10 MENIT!\", 360, 560, 112, WH, 0.65);\nfor (let i = 0; i < 8; i++) s.sfx(\"pop\", 0.1 + i * 0.06, 0.5);\ns.sfx(\"tada\", 0.7, 0.6);\nconfetti(1.1);"
