      "menara balok isometrik tersusun di atas ubin",
      "const I = \"#5b5bf0\", O = \"#ffb84d\", M = \"#3ad1a0\", P = \"#ff6b8b\", L = \"#dcdafc\";\n// drop in from above: returns the extra height while falling and the alpha\nconst drop = (t0, len = 0.35) => {\n  const f = s.clamp((s.t - t0) / len, 0, 1);\n  return { up: (1 - s.ease.out(f)) * 260, a: f > 0 ? 1 : 0 };\n};\nconst k = s.pop(0, 0.4);\ns.isoBox(0, 0, -24, 320, 24, 320, { fill: L, draw: k });\nconst bush = (i, j, t0) => {\n  const d = s.pop(t0, 0.35);\n  s.isoCylinder(i, j, 0, 26 * d + 0.1, 30, { fill: M });\n};\nbush(-115, -115, 0.15);\nbush(115, -115, 0.2);\nconst cols = [I, O, M, P, I];\nfor (let n = 0; n < 5; n++) {\n  const t0 = 0.25 + n * 0.22, w = 170 - n * 22;\n  s.sfx(\"thud\", t0 + 0.3, 0.6);\n  const q = drop(t0);\n  if (q.a) s.isoBox(0, 0, n * 56 + q.up, w, 56, w, { fill: cols[n] });\n}\nbush(-115, 115, 0.25);\nbush(115, 115, 0.3);\ns.sfx(\"ding\", 1.7);\nconst [cx, cy] = s.iso(0, 0, 280 + 40);\ns.cone(cx, cy, 52, 80, { rx: -0.6, ortho: true, fill: P, edges: \"none\", draw: s.pop(1.6, 0.4) });"
