      "const N = \"#1d2340\", CR = \"#fff6e6\", TE = \"#1fc2a7\", OR = \"#ff8a3d\", YE = \"#ffd23f\";\nconst flat = { wobble: 0, hatch: false };\nconst card = (cx, cy, w, h, fill, k, r = 18) => s.group({ x: cx, y: cy, scale: k }, () => {\n  s.rect(-w / 2 + 7, -h / 2 + 8, w, h, { r, fill: N, stroke: \"none\", ...flat });\n  s.rect(-w / 2, -h / 2, w, h, { r, fill, stroke: N, width: 5, ...flat });\n});\nconst book = (cx, cy, w, h, col, k, rot = 0) => s.group({ x: cx, y: cy, scale: k, rotate: rot }, () => {\n  s.rect(-w / 2 + 6, -h / 2 + 7, w, h, { r: 8, fill: N, stroke: \"none\", ...flat });\n  s.rect(-w / 2, -h / 2, w, h, { r: 8, fill: col, stroke: N, width: 5, ...flat });\n  s.rect(-w / 2 + 14, -h / 2 + 10, w - 28, h * 0.22, { r: 4, fill: CR, stroke: N, width: 3, ...flat });\n});\nconst head = (a, b, ink, hl) => {\n  s.text3d(a, 360, 190, { size: 58, depth: 0, color: ink, draw: s.at(0, 0.3) });\n  const w = s.ease.out(s.clamp((s.t - 0.3) / 0.35, 0, 1));\n  if (w > 0) s.group({ x: 360, y: 282, rotate: -0.04 }, () => s.rect(-230 * w, -38, 460 * w, 76, { r: 10, fill: hl, stroke: N, width: 5, ...flat }));\n  s.text3d(b, 360, 282, { size: 76, depth: 0, color: N, draw: s.at(0.35, 0.35) });\n};\nhead(\"SETAHUN =\", \"12 BUKU\", CR, YE);\n// a shelf fills with twelve spines while the counter climbs\nconst sk = s.pop(0.3, 0.35);\ns.rect(70, 720, 580 * sk, 22, { r: 6, fill: CR, stroke: N, width: 5, ...flat });\nconst cols = [OR, YE, CR, TE];\nlet n = 0;\nfor (let i = 0; i < 12; i++) {\n  const t0 = 0.6 + i * 0.11, k = s.pop(t0, 0.25);\n  if (k <= 0) continue;\n  n = i + 1;\n  if (i % 3 === 0) s.sfx(\"tick\", t0, 0.5);\n  const h = 120 + ((i * 37) % 50), x = 92 + i * 46;\n  s.rect(x, 720 - h * k, 38, h * k, { r: 5, fill: cols[i % 4], stroke: N, width: 4, ...flat });\n  s.line(x + 8, 720 - h * k + 20, x + 30, 720 - h * k + 20, { stroke: N, width: 3, ...flat });\n}\nconst c = s.pop(0.6, 0.3);\ncard(360, 450, 240, 120, CR, c, 24);\nif (c > 0) s.text3d(n + \" / 12\", 360, 452, { size: 60, depth: 0, color: N, alpha: c });\nif (n === 12) s.sfx(\"ding\", 1.95, 0.7);"
