      "lingkaran napas yang mengembang dan mengempis pelan di samping pohon bulat, daun melayang turun",
      "const DG = \"#2f4a3a\", SG = \"#6f8f72\", SG2 = \"#a9bfa5\", WH = \"#ffffff\", TC = \"#d9734e\", CR = \"#f5f2ea\";\nconst flat = { wobble: 0, hatch: false };\nconst line = { stroke: DG, width: 3, ...flat };\nconst glow = (x, y, r, a) => { for (let i = 3; i > 0; i--) s.circle(x, y, r * (0.7 + i * 0.3), { fill: TC, stroke: \"none\", alpha: a * 0.1, ...flat }); };\n// leaves drifting down and swaying, looping\nconst leaves = (n, x0, x1, y0, y1, a = 1) => {\n  for (let i = 0; i < n; i++) {\n    const p = (s.t * 0.18 + s.rand(i)) % 1, x = s.lerp(x0, x1, s.rand(i + 7)) + Math.sin(s.t * 1.3 + i) * 24;\n    s.group({ x, y: s.lerp(y0, y1, p), rotate: Math.sin(s.t * 2 + i) * 0.8 }, () => s.ellipse(0, 0, 11, 5, { fill: i % 3 ? SG : TC, stroke: \"none\", alpha: a * Math.min(1, (1 - p) * 3), ...flat }));\n  }\n};\n// a round tree, leaves drifting down, and a soft circle that breathes in and out\nconst k = s.at(0, 0.8);\ns.group({ x: 0, y: (1 - k) * 20, alpha: k }, () => {\n  s.rect(546, 760, 14, 170, { r: 6, fill: DG, stroke: \"none\", ...flat });\n  for (const [dx, dy, r] of [[0, 0, 70], [-50, 40, 52], [50, 36, 56], [0, -50, 50]]) s.circle(553 + dx, 700 + dy, r, { fill: SG, stroke: \"none\", ...flat });\n});\nleaves(7, 420, 680, 640, 930);\nconst b = 0.5 - 0.5 * Math.cos(Math.max(0, s.t - 0.6) * 1.6);\nglow(230, 640, 70 + 40 * b, s.at(0.6, 0.6));\ns.circle(230, 640, 60 + 36 * b, { fill: CR, stroke: TC, width: 3, alpha: s.at(0.6, 0.6), ...flat });\ns.text(b > 0.5 ? \"hembuskan\" : \"tarik napas\", 230, 642, { size: 20, color: DG, alpha: s.at(0.8, 0.5) });\ns.sfx(\"rise\", 0.6, 0.25);"
