      "const ICE = \"#e6f4f1\", ACC = \"#ffb000\", DIM = \"#4d6461\";\nconst flat = { wobble: 0, hatch: false };\n// a word that slides up and fades in, left-aligned at (x, y)\nconst rise = (str, x, y, size, t0, col = ICE) => {\n  const k = s.ease.out(s.clamp((s.t - t0) / 0.35, 0, 1));\n  if (k <= 0) return;\n  s.text3d(str, x, y + (1 - k) * size * 0.9, { size, depth: 0, color: col, align: \"left\", alpha: Math.min(1, k * 1.6) });\n};\n// one digit rolling like an odometer to its final value\nconst roll = (x, y, size, to, t0, len) => {\n  const f = s.ease.out(s.clamp((s.t - t0) / len, 0, 1)), v = f * (10 + to);\n  for (const d of [Math.floor(v), Math.floor(v) + 1]) {\n    const off = (d - v) * size * 1.05;\n    if (Math.abs(off) < size) s.text3d(String(d % 10), x, y + off, { size, depth: 0, color: ICE, alpha: 1 - Math.abs(off) / size });\n  }\n};\nrise(\"SEMALAM\", 70, 330, 96, 0.1);\nrise(\"TIDUR\", 70, 440, 96, 0.4);\nrise(\"JAM BERAPA?\", 70, 560, 110, 0.7, ACC);\nconst u = s.at(1.3, 0.4);\nif (u > 0) s.rect(74, 640, 420 * u, 10, { fill: ACC, stroke: \"none\", ...flat });\ns.sfx(\"swish\", 0.1, 0.4);\ns.sfx(\"swish\", 0.4, 0.4);\ns.sfx(\"impact\", 0.7, 0.6);"
