      "tokoh kotak hijau neon yang berlari dan melompati duri di atas platform bergaris neon, koin +1",
      "const GN = \"#39ff88\", OR = \"#ff8a1f\", VI = \"#b38cff\", WH = \"#ffffff\", RD = \"#ff4d6d\";\nconst flat = { wobble: 0, hatch: false };\nconst glow = (col, blur, fn) => { ctx.save(); ctx.shadowColor = col; ctx.shadowBlur = blur; fn(); ctx.restore(); };\n// hollow neon lettering: a glowing outline with a thin white core\nconst neon = (str, x, y, size, col, t0) => {\n  const k = s.at(t0, 0.25), flick = s.t - t0 < 0.4 && Math.floor(s.t * 30) % 3 === 0 ? 0.3 : 1;\n  if (k <= 0) return;\n  ctx.save();\n  ctx.font = \"400 \" + size + 'px \"Archivo Black\", \"Arial Black\", sans-serif';\n  ctx.textAlign = \"center\";\n  ctx.textBaseline = \"middle\";\n  ctx.globalAlpha = k * flick;\n  ctx.lineJoin = \"round\";\n  ctx.shadowColor = col; ctx.shadowBlur = 22;\n  ctx.strokeStyle = col; ctx.lineWidth = 6; ctx.strokeText(str, x, y);\n  ctx.shadowBlur = 0; ctx.strokeStyle = WH; ctx.lineWidth = 1.5; ctx.strokeText(str, x, y);\n  ctx.restore();\n};\n// a neon-outlined platform block\nconst block = (x, y, w, h, col) => glow(col, 16, () => s.rect(x, y, w, h, { r: 6, stroke: col, width: 4, fill: \"rgba(255,255,255,0.03)\", ...flat }));\n// the hero: a plain glowing square (no face) with a lighter inner rim\nconst hero = (x, y, sq = 0) => glow(GN, 20, () => {\n  s.rect(x - 26 - sq * 6, y - 52 + sq * 12, 52 + sq * 12, 52 - sq * 12, { r: 8, fill: GN, stroke: \"none\", ...flat });\n  s.rect(x - 18 - sq * 6, y - 44 + sq * 12, 36 + sq * 12, 36 - sq * 12, { r: 5, fill: \"none\", stroke: \"#c8ffdf\", width: 2, ...flat });\n});\nblock(40, 700, 640, 40, VI);\n// spikes in the way, a coin above them\nglow(RD, 14, () => s.shape([[330, 700], [360, 640], [390, 700]], { fill: \"none\", stroke: RD, width: 4, ...flat }));\nconst got = s.t > 1.15;\nif (!got) glow(OR, 16, () => s.circle(360, 470 + s.wave(2, 6), 22, { fill: OR, stroke: \"none\", ...flat }));\n// the hero runs in and leaps the spikes in an arc\nconst f = s.clamp((s.t - 0.4) / 1.4, 0, 1), x = 100 + 520 * f;\nconst air = s.clamp((x - 230) / 260, 0, 1), y = 700 - Math.sin(air * Math.PI) * 260;\nhero(x, y);\nfor (let i = 1; i < 5; i++) { const g = Math.max(0, f - i * 0.03), gx = 100 + 520 * g, ga = s.clamp((gx - 230) / 260, 0, 1); s.rect(gx - 8, 700 - Math.sin(ga * Math.PI) * 260 - 34, 16, 16, { r: 4, fill: GN, stroke: \"none\", alpha: 0.5 - i * 0.1, ...flat }); }\nif (got) { const k = s.pop(1.15, 0.3); s.text3d(\"+1\", 400, 430 - (s.t - 1.15) * 40, { size: 48, depth: 0, color: OR, alpha: k * Math.max(0, 1 - (s.t - 1.6)) }); }\ns.sfx(\"swish\", 0.75, 0.4);\ns.sfx(\"coin\", 1.15, 0.6);"
