      "dua lingkaran garis tipis yang saling mendekat, irisannya terisi biru kobalt, label mono kecil bernomor",
      "const CB = \"#2b59ff\", INK = s.theme === \"night\" ? \"#eef0f7\" : \"#16171c\", MU = \"#9097a8\", SOFT = \"rgba(43,89,255,0.14)\";\nconst flat = { wobble: 0, hatch: false };\n// a small mono caption with a short rule before it\nconst lab = (str, x, y, t0, col = MU) => {\n  const k = s.at(t0, 0.3);\n  if (k <= 0) return;\n  s.line(x, y, x + 34 * k, y, { stroke: col, width: 3, ...flat });\n  s.text(str, x + 48, y + 1, { size: 24, color: col, align: \"left\", alpha: k });\n};\n// a second ring slides in and the overlap fills blue\nconst x2 = s.lerp(700, 450, s.ease.out(s.clamp((s.t - 0.3) / 0.8, 0, 1)));\ns.circle(270, 470, 150, { stroke: INK, width: 3, fill: \"none\", ...flat });\ns.circle(x2, 470, 150, { stroke: INK, width: 3, fill: \"none\", ...flat });\nconst o = s.at(1.1, 0.5);\nif (o > 0) {\n  const pts = [];\n  const d = x2 - 270, h = Math.sqrt(Math.max(0, 150 * 150 - (d / 2) * (d / 2))), a = Math.atan2(h, d / 2);\n  for (let i = 0; i <= 20; i++) { const t = -a + (2 * a * i) / 20; pts.push([270 + Math.cos(t) * 150, 470 + Math.sin(t) * 150]); }\n  for (let i = 0; i <= 20; i++) { const t = Math.PI - a + (2 * a * i) / 20; pts.push([x2 + Math.cos(t) * 150, 470 + Math.sin(t) * 150]); }\n  s.shape(pts, { fill: CB, stroke: \"none\", alpha: o, ...flat });\n}\nlab(\"02  BERDUA\", 150, 690, 1.4, CB);\ns.sfx(\"slide\", 0.3, 0.4);\ns.sfx(\"pop\", 1.1, 0.4);"
