      "sembilan titik di grid yang tersambung garis satu per satu, simpul tengah biru",
      "const CB = \"#2b59ff\", INK = s.theme === \"night\" ? \"#eef0f7\" : \"#16171c\", MU = \"#9097a8\", SOFT = \"rgba(43,89,255,0.14)\";\nconst flat = { wobble: 0, hatch: false };\n// a small mono caption with a short rule before it\nconst lab = (str, x, y, t0, col = MU) => {\n  const k = s.at(t0, 0.3);\n  if (k <= 0) return;\n  s.line(x, y, x + 34 * k, y, { stroke: col, width: 3, ...flat });\n  s.text(str, x + 48, y + 1, { size: 24, color: col, align: \"left\", alpha: k });\n};\n// nine dots on a grid, then the lines that join them draw in\nconst P = [];\nfor (let i = 0; i < 9; i++) P.push([210 + (i % 3) * 150, 330 + Math.floor(i / 3) * 150]);\nconst E = [[0, 1], [1, 2], [3, 4], [4, 5], [6, 7], [7, 8], [0, 3], [3, 6], [1, 4], [4, 7], [2, 5], [5, 8], [0, 4], [4, 8], [2, 4], [4, 6]];\nE.forEach(([a, b], i) => s.line(P[a][0], P[a][1], P[b][0], P[b][1], { stroke: i > 11 ? CB : INK, width: i > 11 ? 4 : 2, draw: s.at(0.6 + i * 0.07, 0.25), ...flat }));\nP.forEach(([x, y], i) => { const k = s.pop(0.1 + i * 0.05, 0.3); if (k > 0) s.circle(x, y, (i === 4 ? 18 : 11) * k, { fill: i === 4 ? CB : INK, stroke: \"none\", ...flat }); });\nlab(\"03  TIM\", 210, 690, 1.8);\ns.sfx(\"pop\", 0.1, 0.3);\ns.sfx(\"swish\", 0.6, 0.3);"
