      "layar terbelah: blok merah meluncur masuk lalu angka 3 raksasa krem jatuh di atasnya, kata hitam di sebelah",
      "const BK = \"#111111\", RD = \"#e63323\", CR = \"#f2efe8\", YE = \"#ffd400\";\nconst flat = { wobble: 0, hatch: false };\n// a block that slides in from one side (dir 1 = from the left, -1 = from the right)\nconst panel = (x, y, w, h, col, t0, dir = 1, len = 0.4) => {\n  const k = s.ease.out(s.clamp((s.t - t0) / len, 0, 1));\n  if (k <= 0) return;\n  s.rect(dir > 0 ? x : x + w * (1 - k), y, w * k, h, { fill: col, stroke: \"none\", ...flat });\n};\n// a word that drops into place and stays perfectly still\nconst drop = (str, x, y, size, col, t0, align = \"left\") => {\n  const k = s.ease.out(s.clamp((s.t - t0) / 0.3, 0, 1));\n  if (k > 0) s.text3d(str, x, y - (1 - k) * 80, { size, depth: 0, color: col, align, alpha: Math.min(1, k * 2) });\n};\n// the screen splits into a red half; a giant 3 drops onto it\npanel(0, 0, 360, 1280, RD, 0.1, 1, 0.45);\ndrop(\"3\", 180, 520, 420, CR, 0.5, \"center\");\ndrop(\"HAL\", 400, 440, 110, BK, 0.8);\ndrop(\"SAJA.\", 400, 560, 110, BK, 1.0);\ns.sfx(\"whip\", 0.1, 0.6);\ns.sfx(\"impact\", 0.5, 0.8);\ns.sfx(\"snap\", 0.8, 0.5);\ns.sfx(\"snap\", 1.0, 0.5);"
