      "rumah dua lantai terbelah: kamar kiri atas menyala, ruangan lain meredup, jam weker bergetar dan tokoh bangun dari kasur",
      "const INK = \"#3b2f2a\", PA = \"#fbf6ea\", WD = \"#b77a4c\", YE = \"#f3c94f\", TC = \"#d9764a\", BL = \"#4a7ab7\";\nconst ink = (w = 3) => ({ stroke: INK, width: w, wobble: 1.2, hatch: false });\n// the four rooms of the house behind: 0 top left, 1 top right, 2 bottom left, 3 bottom right\nconst ROOM = [[60, 300, 360, 560], [360, 300, 660, 560], [60, 560, 360, 840], [360, 560, 660, 840]];\n// every room but the lit one sinks into shade\nconst spot = (on, k = 1) => ROOM.forEach(([x0, y0, x1, y1], i) => { if (i !== on) s.rect(x0, y0, x1 - x0, y1 - y0, { fill: \"#1b1626\", stroke: \"none\", alpha: 0.42 * k, wobble: 0, hatch: false }); });\nconst ME = { size: 190, shirt: BL, pants: \"#3b3f55\", hair: \"curly\", hairColor: INK };\nconst note = (str, x, y, t0, col = TC) => s.text(str, x, y, { size: 30, color: col, draw: s.at(t0, 0.4), rotate: -0.08 });\nspot(0, s.at(0, 0.4));\n// the bed, the alarm clock rattling on its stool, the sleeper sitting up\ns.rect(80, 480, 200, 50, { r: 8, fill: PA, ...ink() });\ns.rect(80, 470, 60, 30, { r: 10, fill: \"#ffffff\", ...ink(2.5) });\ns.rect(130, 488, 150, 40, { r: 8, fill: \"#e98b8b\", ...ink(2.5) });\nconst shake = s.t < 1.4 ? Math.sin(s.t * 70) * 3 : 0;\ns.rect(300, 500, 40, 52, { fill: WD, ...ink(2.5) });\ns.group({ x: 320 + shake, y: 482 }, () => { s.circle(0, 0, 16, { fill: YE, ...ink(2.5) }); s.line(0, 0, 0, -9, ink(2)); s.line(0, 0, 7, 0, ink(2)); });\nif (s.t < 1.4) for (const d of [-1, 1]) s.line(320 + d * 24, 470, 320 + d * 34, 460, ink(2));\nnote(\"kring!\", 300, 430, 0.2);\ns.person(170, 532, { ...ME, pose: [[\"sit\", 0], [\"cheer\", 1.3]] });\ns.sfx(\"tock\", 0.2, 0.5);\ns.sfx(\"tock\", 0.5, 0.5);"
