      "dua lempeng warna miring yang menghentak masuk dengan kata tebal, lalu panah zigzag putih",
      "const CB = \"#1f3cff\", OR = \"#ff7a00\", WH = \"#ffffff\", INK = \"#0d0d0d\", MT = \"#b8ff3c\";\nconst flat = { wobble: 0, hatch: false };\n// a rotated slab of colour with a bold word on it, slamming down from a bigger size\nconst slab = (str, x, y, w, rot, fill, col, t0, size = 76) => {\n  const k = s.ease.out(s.clamp((s.t - t0) / 0.22, 0, 1));\n  if (k <= 0) return;\n  s.group({ x, y, rotate: rot, scale: 1.5 - 0.5 * k, alpha: Math.min(1, k * 2) }, () => {\n    s.rect(-w / 2, -size * 0.75, w, size * 1.5, { fill, stroke: \"none\", ...flat });\n    s.text3d(str, 0, 4, { size, depth: 0, color: col });\n  });\n};\n// a jagged price badge (a star with many short points), turning slowly\nconst badge = (x, y, r, fill, k) => s.group({ x, y, scale: k, rotate: s.t * 0.4 }, () => s.shape(s.shapes.star(18, r, r * 0.84), { fill, stroke: \"none\", ...flat }));\n// a zigzag arrow drawn towards (x1, y1)\nconst zig = (x0, y0, x1, y1, t0, col = INK) => {\n  const pts = [];\n  for (let i = 0; i <= 6; i++) { const f = i / 6, side = i % 2 ? 1 : -1; pts.push([x0 + (x1 - x0) * f - side * 18 * (1 - f), y0 + (y1 - y0) * f + side * 18 * (1 - f)]); }\n  const d = s.at(t0, 0.3);\n  s.polyline(pts, { stroke: col, width: 9, draw: d, ...flat });\n  if (d >= 1) { const a = Math.atan2(y1 - pts[5][1], x1 - pts[5][0]); s.shape([[x1 + Math.cos(a) * 20, y1 + Math.sin(a) * 20], [x1 + Math.cos(a + 2.4) * 30, y1 + Math.sin(a + 2.4) * 30], [x1 + Math.cos(a - 2.4) * 30, y1 + Math.sin(a - 2.4) * 30]], { fill: col, stroke: \"none\", ...flat }); }\n};\nslab(\"KELAS DESAIN\", 340, 380, 600, -0.06, INK, WH, 0.1, 74);\nslab(\"BUKA LAGI!\", 380, 520, 520, 0.05, OR, INK, 0.45, 86);\nzig(120, 760, 260, 620, 0.9, WH);\ns.sfx(\"impact\", 0.1, 0.8);\ns.sfx(\"impact\", 0.45, 0.8);\ns.sfx(\"whip\", 0.9, 0.5);"
