      "const CO = \"#f07a5a\", TE = \"#2a9d8f\", YE = \"#f6c143\", NV = \"#26355d\", CR = \"#fffaf0\", WH = \"#ffffff\", INK = \"#2b2a28\";\nconst flat = { stroke: \"none\", wobble: 0, hatch: false };\n// every cut-out sits on a soft paper shadow\nconst cut = (fn) => { s.group({ x: 4, y: 6, alpha: 0.16 }, () => fn(INK)); fn(null); };\n// a paper tag pinned to the sheet with a round thumbtack\nconst tag = (str, x, y, col, t0, rot = 0.03) => {\n  const k = s.pop(t0, 0.35);\n  if (k <= 0) return;\n  s.group({ x, y, rotate: rot, scale: k }, () => {\n    const w = str.length * 20 + 50;\n    cut((sh) => s.rect(-w / 2, -28, w, 58, { r: 5, fill: sh ?? col, ...flat }));\n    s.text(str, 0, 4, { size: 30, color: col === CR ? INK : WH });\n    s.circle(0, -28, 10, { fill: CO, ...flat });\n    s.circle(-3, -31, 3.5, { fill: \"rgba(255,255,255,0.6)\", ...flat });\n  });\n};\n// the paper Earth: a blue disc with green land cut-outs that slide round as it spins\nconst earth = (x, y, r, spin, k = 1) => s.group({ x, y, scale: k }, () => {\n  cut((sh) => s.circle(0, 0, r, { fill: sh ?? \"#4f8fd9\", ...flat }));\n  for (const [a, w, h, dy] of [[0, 0.5, 0.34, -0.35], [2.1, 0.4, 0.5, 0.2], [4.2, 0.55, 0.3, 0.45]]) {\n    const p = ((a + spin) % (Math.PI * 2)) - Math.PI;\n    if (Math.abs(p) > 1.35) continue;\n    s.ellipse(Math.sin(p) * r * 0.75, dy * r, w * r * Math.cos(p), h * r, { fill: \"#5cb85c\", ...flat });\n  }\n});\nconst sun = (x, y, r, k = 1) => s.group({ x, y, scale: k, rotate: s.t * 0.3 }, () => {\n  for (let i = 0; i < 10; i++) {\n    const a = (i / 10) * Math.PI * 2;\n    s.shape([[Math.cos(a - 0.15) * r * 1.05, Math.sin(a - 0.15) * r * 1.05], [Math.cos(a) * r * 1.45, Math.sin(a) * r * 1.45], [Math.cos(a + 0.15) * r * 1.05, Math.sin(a + 0.15) * r * 1.05]], { fill: \"#f4a63a\", ...flat });\n  }\n  cut((sh) => s.circle(0, 0, r, { fill: sh ?? YE, ...flat }));\n});\n// a paper clock whose hand runs a full lap while the count climbs to 24\nconst k = s.pop(0.2, 0.45);\ns.group({ x: 360, y: 460, scale: k }, () => {\n  cut((sh) => s.circle(0, 0, 190, { fill: sh ?? CR, ...flat }));\n  s.circle(0, 0, 170, { fill: WH, ...flat });\n  for (let i = 0; i < 24; i++) {\n    const a = (i / 24) * Math.PI * 2;\n    s.circle(Math.sin(a) * 150, -Math.cos(a) * 150, i % 6 ? 4 : 8, { fill: i % 6 ? \"#c9c2b0\" : NV, ...flat });\n  }\n  const f = s.ease.inOut(s.clamp((s.t - 0.6) / 1.6, 0, 1)), a = f * Math.PI * 2;\n  s.line(0, 0, Math.sin(a) * 130, -Math.cos(a) * 130, { stroke: CO, width: 9, wobble: 0, hatch: false });\n  s.circle(0, 0, 12, { fill: NV, ...flat });\n  s.text3d(String(Math.round(24 * f)), 0, 70, { size: 54, depth: 0, color: NV });\n});\ntag(\"1 PUTARAN\", 360, 740, TE, 2.2);\ns.sfx(\"tick\", 0.6, 0.3);\ns.sfx(\"tick\", 1.2, 0.3);\ns.sfx(\"tick\", 1.8, 0.3);\ns.sfx(\"ding\", 2.2, 0.5);"
