export function getSatsetStyleDemoScenes(styleId?: string | null, customDemo?: SatsetDemoScene[]): SatsetDemoScene[] {
  if (customDemo && customDemo.length > 0) {
    return customDemo.map((d) => ({ ...d, duration: d.duration || 4.2 }));
  }
  const resolved = resolveSatsetStyleId(styleId);
  const tupleList = SATSET_RAW_STYLE_DEMOS[resolved] || SATSET_RAW_STYLE_DEMOS[styleId || ""] || SATSET_RAW_STYLE_DEMOS.scribble3d;
  return tupleList.map(([text, emphasis, theme, code]) => ({
    text,
    emphasis: Array.isArray(emphasis) ? emphasis.join(" ") : String(emphasis || ""),
    theme: theme || "paper",
    code,
    duration: 4.2,
  }));
}

export function getSatsetStyleExamples(styleId?: string | null): Array<[string, string]> | undefined {
  if (!styleId) return undefined;
  const resolved = resolveSatsetStyleId(styleId);
  return SATSET_STYLE_EXAMPLES[resolved] || SATSET_STYLE_EXAMPLES[styleId];
}
